import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.C-si7TFR.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/trigger_weixin_official_account.md","filePath":"zh/trigger_weixin_official_account.md"}'),l={name:"zh/trigger_weixin_official_account.md"};function i(n,e,p,c,u,s){return t(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="微信公众号触发器" tabindex="-1">微信公众号触发器 <a class="header-anchor" href="#微信公众号触发器" aria-label="Permalink to &quot;微信公众号触发器&quot;">​</a></h2><h3 id="创建微信公众号工作流" tabindex="-1">创建微信公众号工作流 <a class="header-anchor" href="#创建微信公众号工作流" aria-label="Permalink to &quot;创建微信公众号工作流&quot;">​</a></h3><p>如下，创建一个简单的工作流，用于响应公众号发送的消息，这里我们只是简单的回复：你好。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="配置微信公众号开发信息" tabindex="-1">配置微信公众号开发信息 <a class="header-anchor" href="#配置微信公众号开发信息" aria-label="Permalink to &quot;配置微信公众号开发信息&quot;">​</a></h3><p>扫码登陆<a href="https://mp.weixin.qq.com/cgi-bin/home?t=home/index&amp;lang=zh_CN" target="_blank" rel="noreferrer">微信公众号后台</a>，进入【设置与开发】=》【基本配置】页面下，我们可以看到几个需要用到的信息：</p><ul><li>AppID：开发者ID。</li><li>AppSecret：开发者密钥。</li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>拿到上面的AppID和AppSecret后，打开Botman创建【微信公众号】类型的凭据，输入上面的AppID和AppSecret。</p><p>同时，该页面会自动生成<strong>Token</strong>、<strong>EncodingAESKey</strong>和<strong>回调地址</strong>，把这两个信息配置到公众号【基本配置】下的【服务器配置】选项里的<strong>令牌(Token)、消息加解密钥(EncodingAESKey)<strong>和</strong>服务器地址(URL)</strong>，消息加密方式使用<strong>安全模式</strong>。最后点击保存即可。</p><blockquote><p>原截图含凭据、令牌或应用标识，已停止公开。请在对应平台自行创建秘密并填入本地配置。</p></blockquote><h3 id="配置响应消息" tabindex="-1">配置响应消息 <a class="header-anchor" href="#配置响应消息" aria-label="Permalink to &quot;配置响应消息&quot;">​</a></h3><p>如上图，在【高级配置】下，启用自动回复。可以设置响应的消息类型，目前支持以下几种：</p><ul><li>Text：文本。</li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><ul><li><p>Image：图片。</p><p>点击上传小于200KB的图片。</p></li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><ul><li>Text+Image：图文。</li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><ul><li><p>Exec Workflow：下拉可以选择启用的微信公众号触发器工作流。</p><p>注意：由于微信官方要求，对于公众号发送的消息，必须要在5秒内响应回复，所以工作流这里在发送公众号消息之前不能做耗时的业务操作。</p></li></ul><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote>',21)])])}const g=o(l,[["render",i]]);export{h as __pageData,g as default};
